statement.tex:
正六角形 ABCDEF において $\overrightarrow{\mathrm{AB}}=\vec a$，$\overrightarrow{\mathrm{AF}}=\vec b$ とする．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{AC}},\ \overrightarrow{\mathrm{AD}},\ \overrightarrow{\mathrm{AE}}$ を $\vec a,\vec b$ で表せ．
  \item 線分 AC と BF の交点を P とするとき，$\overrightarrow{\mathrm{AP}}$ を $\vec a,\vec b$ で表せ．
\end{enumerate}

$AB=4,\ BC=5,\ CA=6$ の $\triangle ABC$ の内心を I，$\angle A$ 内の傍心（辺 BC に接する傍接円の中心）を J とする．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{AI}}$ を $\overrightarrow{\mathrm{AB}},\overrightarrow{\mathrm{AC}}$ で表せ．
  \item $\overrightarrow{\mathrm{AJ}}$ を $\overrightarrow{\mathrm{AB}},\overrightarrow{\mathrm{AC}}$ で表し，$\overrightarrow{\mathrm{AJ}}=3\overrightarrow{\mathrm{AI}}$ であることを確かめよ．
\end{enumerate}

平面上に四角形 ABCD と点 P がある．点 A に関する P の対称点を Q，点 B に関する Q の対称点を R，点 C に関する R の対称点を S，点 D に関する S の対称点を T とする．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{PT}}$ は P の位置によらないことを示せ．
  \item ABCD が平行四辺形ならば，T は P と一致することを示せ．
\end{enumerate}

$\triangle ABC$ と点 P が $2\overrightarrow{\mathrm{PA}}+3\overrightarrow{\mathrm{PB}}+4\overrightarrow{\mathrm{PC}}=\vec0$ を満たす．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{AP}}$ を $\overrightarrow{\mathrm{AB}},\overrightarrow{\mathrm{AC}}$ で表せ．
  \item 直線 AP と辺 BC の交点を D とする．$BD:DC$ と $AP:PD$ を求めよ．
  \item $\triangle PBC:\triangle PCA:\triangle PAB$ を求めよ．
\end{enumerate}

$\triangle OAB$ で $\overrightarrow{\mathrm{OA}}=\vec a,\ \overrightarrow{\mathrm{OB}}=\vec b$ とする．辺 OA を $2:1$ に内分する点を C，辺 OB を $1:2$ に内分する点を D とし，AD と BC の交点を P とする．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{OP}}$ を $\vec a,\vec b$ で表せ．
  \item 直線 OP と辺 AB の交点を Q とするとき，$AQ:QB$ を求めよ．
  \item $|\vec a|=2,\ |\vec b|=3,\ \angle AOB=60^\circ$ のとき，$|\overrightarrow{\mathrm{OP}}|$ を求めよ．
\end{enumerate}

$\triangle ABC$ で $AB=3,\ AC=4,\ \angle A=60^\circ$ とする．頂点 A から辺 BC に下ろした垂線の足を H とする．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{AH}}$ を $\overrightarrow{\mathrm{AB}},\overrightarrow{\mathrm{AC}}$ で表せ．
  \item $|\overrightarrow{\mathrm{AH}}|$ を求めよ．
\end{enumerate}

$AB=2,\ AC=3,\ BC=\sqrt7$ の $\triangle ABC$ の外心を O，垂心を H とする．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{AO}}$ を $\overrightarrow{\mathrm{AB}},\overrightarrow{\mathrm{AC}}$ で表せ．
  \item $\overrightarrow{\mathrm{AH}}$ を $\overrightarrow{\mathrm{AB}},\overrightarrow{\mathrm{AC}}$ で表せ．
\end{enumerate}

$|\vec a|=3,\ |\vec b|=4,\ \vec a\cdot\vec b=6$ で，$\overrightarrow{\mathrm{OA}}=\vec a,\ \overrightarrow{\mathrm{OB}}=\vec b$，$\overrightarrow{\mathrm{OP}}=\frac12\vec a+\frac13\vec b$ とする．
\begin{enumerate}
  \item $\triangle OAB$ の面積を求めよ．
  \item $\triangle PAB$ と $\triangle OPB$ の面積を求めよ．
\end{enumerate}

O$(0,0)$，A$(4,0)$，B$(0,2)$ とし，点 P は円 $x^2+y^2=1$ 上を動く．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{PA}}\cdot\overrightarrow{\mathrm{PB}}$ の最大値と最小値を求めよ．
  \item $|\overrightarrow{\mathrm{PA}}+\overrightarrow{\mathrm{PB}}|$ の最大値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\triangle ABC$ において $\overrightarrow{\mathrm{AB}}\cdot\overrightarrow{\mathrm{AC}}=\overrightarrow{\mathrm{BA}}\cdot\overrightarrow{\mathrm{BC}}$ が成り立つならば，$CA=CB$ であることを示せ．
  \item 点 O を中心とする半径1の円周上に3点 A，B，C があり，$\overrightarrow{\mathrm{OA}}+2\overrightarrow{\mathrm{OB}}+2\overrightarrow{\mathrm{OC}}=\vec0$ を満たす．$\triangle ABC$ の3辺の長さを求めよ．
\end{enumerate}

四面体 OABC において，$\overrightarrow{\mathrm{OQ}}=\overrightarrow{\mathrm{OA}}+2\overrightarrow{\mathrm{OB}}+3\overrightarrow{\mathrm{OC}}$ で点 Q を定める．直線 OQ と平面 ABC の交点を R とする．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{OR}}$ を $\overrightarrow{\mathrm{OA}},\overrightarrow{\mathrm{OB}},\overrightarrow{\mathrm{OC}}$ で表せ．
  \item $\triangle RBC:\triangle RCA:\triangle RAB$ を求めよ．
\end{enumerate}

1辺の長さが1の正四面体 OABC について，
\begin{enumerate}
  \item 面 OBC と面 ABC のなす角を $\theta$ とするとき，$\cos\theta$ を求めよ．
  \item 辺 OA と平面 ABC のなす角を $\varphi$ とするとき，$\cos\varphi$ を求めよ．
  \item 辺 OA の中点 M と辺 BC の中点 N について，MN の長さを求め，MN が OA，BC の両方に垂直であることを示せ．
\end{enumerate}

3点 A$(1,0,0)$，B$(0,2,0)$，C$(0,0,3)$ がある．
\begin{enumerate}
  \item 点 D$(1,1,1)$ を通り方向ベクトルが $(1,1,1)$ の直線と，平面 ABC の交点を求めよ．
  \item 点 P$(p,\ 1-p,\ 2)$ が平面 ABC 上にあるような $p$ を求めよ．
\end{enumerate}

3点 A$(1,0,0)$，B$(0,1,0)$，C$(0,0,1)$ がある．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{AB}},\overrightarrow{\mathrm{AC}}$ の両方に垂直な単位ベクトルを求めよ．
  \item 点 D を $\triangle ABC$ を1つの面とする正四面体 ABCD の頂点となるようにとる．D の座標をすべて求めよ．
\end{enumerate}

3点 A$(2,0,0)$，B$(0,4,0)$，C$(0,0,4)$ を通る平面を $\alpha$ とする．
\begin{enumerate}
  \item 原点 O から $\alpha$ に下ろした垂線の足 H の座標を求めよ．
  \item 四面体 OABC の体積を利用して，$\triangle ABC$ の面積を求めよ．
  \item $\alpha$ に関して O と対称な点の座標を求めよ．
\end{enumerate}

平面 $\alpha:x+y+z=1$ と2点 P$(1,1,1)$，Q$(2,0,1)$ がある．
\begin{enumerate}
  \item $\alpha$ に関して P と対称な点 P$'$ の座標を求めよ．
  \item 点 X が $\alpha$ 上を動くとき，$PX+XQ$ の最小値と，そのときの X の座標を求めよ．
\end{enumerate}

O$(0,0,0)$，A$(1,2,0)$，B$(0,1,2)$，C$(2,0,1)$ とする．
\begin{enumerate}
  \item 四面体 OABC の体積を求めよ．
  \item $\triangle ABC$ の面積と，O と平面 ABC の距離を求めよ．
\end{enumerate}

A$(1,0,0)$，B$(0,1,0)$，C$(0,0,1)$ とする．空間内の点 P が $\overrightarrow{\mathrm{PA}}\cdot\overrightarrow{\mathrm{PB}}+\overrightarrow{\mathrm{PB}}\cdot\overrightarrow{\mathrm{PC}}+\overrightarrow{\mathrm{PC}}\cdot\overrightarrow{\mathrm{PA}}=0$ を満たしながら動く．
\begin{enumerate}
  \item P はある球面上を動くことを示し，その中心と半径を求めよ．
  \item 四面体 PABC の体積の最大値を求めよ．
\end{enumerate}

球面 $S:x^2+y^2+z^2=9$ と平面 $\alpha:x+2y+2z=6$ の交わりを円 $C$ とする．
\begin{enumerate}
  \item $C$ の中心と半径を求めよ．
  \item 点 D$(0,0,5)$ と $C$ 上の点の距離の最小値と，そのときの $C$ 上の点を求めよ．
\end{enumerate}

$\triangle$OAB において，辺 OA を $2:1$ に内分する点を C，辺 OB を $1:2$ に内分する点を D とする．線分 AD と線分 BC の交点を P とする．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{OP}}$ を $\overrightarrow{\mathrm{OA}}$，$\overrightarrow{\mathrm{OB}}$ で表せ．
  \item $\triangle$OPA，$\triangle$PDB の面積をそれぞれ $S_1,S_2$ とするとき，$S_1:S_2$ を求めよ．
\end{enumerate}

$\triangle$ABC は $\text{AB}=3$，$\text{AC}=5$，$\text{BC}=7$ を満たし，その外接円の中心を O とする．
\begin{enumerate}
  \item $\angle$BAC と，内積 $\overrightarrow{\mathrm{AB}}\cdot\overrightarrow{\mathrm{AO}}$，$\overrightarrow{\mathrm{AC}}\cdot\overrightarrow{\mathrm{AO}}$ を求めよ．
  \item $\overrightarrow{\mathrm{AO}}$ を $\overrightarrow{\mathrm{AB}}$，$\overrightarrow{\mathrm{AC}}$ で表せ．
  \item 直線 AO と直線 BC の交点を D とするとき，BD$:$DC と AD$:$DO を求めよ．
\end{enumerate}

$\triangle$OAB において $|\overrightarrow{\mathrm{OA}}|=2$，$|\overrightarrow{\mathrm{OB}}|=3$，$\overrightarrow{\mathrm{OA}}\cdot\overrightarrow{\mathrm{OB}}=3$ とし，$\vec a=\overrightarrow{\mathrm{OA}}$，$\vec b=\overrightarrow{\mathrm{OB}}$ とおく．
\begin{enumerate}
  \item 直線 OA 上の点 C を $\overrightarrow{\mathrm{BC}}\perp\vec a$ となるようにとる．$\overrightarrow{\mathrm{OC}}$ を $\vec a$ で表せ．
  \item 直線 BC 上の点 H を $\overrightarrow{\mathrm{AH}}\perp\vec b$ となるようにとる．$\overrightarrow{\mathrm{OH}}$ を $\vec a,\vec b$ で表せ．
  \item H は $\triangle$OAB の垂心であることを確かめよ．
\end{enumerate}

$\triangle$ABC において $\text{AB}=6$，$\text{BC}=5$，$\text{CA}=4$ とする．内心を I，$\angle$A 内の傍心（辺 BC と，辺 AB，AC の延長に接する円の中心）を J とする．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{AI}}$ を $\overrightarrow{\mathrm{AB}}$，$\overrightarrow{\mathrm{AC}}$ で表せ．
  \item $\overrightarrow{\mathrm{AJ}}$ を $\overrightarrow{\mathrm{AB}}$，$\overrightarrow{\mathrm{AC}}$ で表せ．
  \item $\triangle$ABC の面積と $\triangle$IBC の面積を求めよ．
\end{enumerate}

$\triangle$ABC において $\overrightarrow{\mathrm{CA}}=\vec a$，$\overrightarrow{\mathrm{CB}}=\vec b$ とする．
\begin{enumerate}
  \item $s\geqq0,\ t\geqq0,\ 1\leqq s+2t\leqq2$ のとき，$\overrightarrow{\mathrm{CP}}=s\vec a+t\vec b$ で定まる点 P の存在範囲の面積は $\triangle$ABC の面積の何倍か．
  \item $s\geqq0,\ t\geqq0,\ s+t\leqq1$ のとき，$\overrightarrow{\mathrm{CP}}=(s+t)\vec a+(s-2t)\vec b$ で定まる点 P の存在範囲の面積は $\triangle$ABC の面積の何倍か．
\end{enumerate}

$\triangle$ABC の外接円の中心を O とし，半径を1とする．$3\overrightarrow{\mathrm{OA}}+4\overrightarrow{\mathrm{OB}}+5\overrightarrow{\mathrm{OC}}=\vec0$ であるとき，
\begin{enumerate}
  \item 内積 $\overrightarrow{\mathrm{OA}}\cdot\overrightarrow{\mathrm{OB}}$，$\overrightarrow{\mathrm{OB}}\cdot\overrightarrow{\mathrm{OC}}$，$\overrightarrow{\mathrm{OC}}\cdot\overrightarrow{\mathrm{OA}}$ を求めよ．
  \item $\triangle$OAB，$\triangle$OBC，$\triangle$OCA の面積と，$\triangle$ABC の面積を求めよ．
\end{enumerate}

平面上において同一直線上にない3点 A，B，C があるとき，次の各式を満たす点 P の集合を求めよ．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{PA}}+\overrightarrow{\mathrm{PB}}+2\overrightarrow{\mathrm{PC}}=\overrightarrow{\mathrm{AB}}$
  \item $\overrightarrow{\mathrm{AP}}\cdot\overrightarrow{\mathrm{AP}}=2\overrightarrow{\mathrm{AB}}\cdot\overrightarrow{\mathrm{AP}}$
  \item $|\overrightarrow{\mathrm{AP}}|^2\leqq\overrightarrow{\mathrm{AP}}\cdot(\overrightarrow{\mathrm{AB}}+\overrightarrow{\mathrm{AC}})$
\end{enumerate}

各辺の長さが1の正四面体 OABC において，辺 OB を $1:2$ に内分する点を D，辺 BC を $2:1$ に内分する点を E，辺 OC の中点を F とする．線分 DE と線分 BF の交点を G とするとき，
\begin{enumerate}
  \item $\overrightarrow{\mathrm{OG}}$ を $\overrightarrow{\mathrm{OB}}$，$\overrightarrow{\mathrm{OC}}$ で表し，G はどのような点か答えよ．
  \item OG，AG の長さを求めよ．
\end{enumerate}

四面体 OABC の辺 AB を $1:2$ に内分する点を D，辺 OC を $1:3$ に内分する点を E とし，線分 DE を $2:1$ に内分する点を P とする．直線 OP が平面 ABC と交わる点を Q とする．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{OA}}=\vec a$，$\overrightarrow{\mathrm{OB}}=\vec b$，$\overrightarrow{\mathrm{OC}}=\vec c$ とするとき，$\overrightarrow{\mathrm{OP}}$，$\overrightarrow{\mathrm{OQ}}$ を表せ．また，$|\overrightarrow{\mathrm{OP}}|:|\overrightarrow{\mathrm{OQ}}|$ を求めよ．
  \item $\triangle$ABQ と $\triangle$ABC の面積比を求めよ．
\end{enumerate}

四面体 OABC において $\overrightarrow{\mathrm{OA}}=\vec a$，$\overrightarrow{\mathrm{OB}}=\vec b$，$\overrightarrow{\mathrm{OC}}=\vec c$ とする．辺 OA の中点を P，辺 AB を $1:2$ に内分する点を Q，辺 BC を $2:1$ に内分する点を R，線分 OC を $t:(1-t)$ に内分する点を S とする（$0<t<1$）．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{PQ}}$，$\overrightarrow{\mathrm{PR}}$，$\overrightarrow{\mathrm{PS}}$ を $\vec a,\vec b,\vec c$ で表せ．
  \item 4点 P，Q，R，S が同一平面上にあるような $t$ の値を求めよ．
\end{enumerate}

平面 $\alpha:2x-y+2z=1$ に関して同じ側に2点 P$(4,0,1)$，Q$(1,-3,2)$ がある．
\begin{enumerate}
  \item 平面 $\alpha$ に関して点 P と対称な点 R の座標を求めよ．
  \item 平面 $\alpha$ 上の点で，$\text{PS}+\text{QS}$ を最小にする点 S の座標と，そのときの最小値を求めよ．
\end{enumerate}

$\triangle$ABC の外心 O から辺 BC，CA，AB にひいた垂線の足をそれぞれ P，Q，R とする．$2\overrightarrow{\mathrm{OP}}+3\overrightarrow{\mathrm{OQ}}+4\overrightarrow{\mathrm{OR}}=\vec0$ が成り立つとき，
\begin{enumerate}
  \item $\overrightarrow{\mathrm{OA}}$ を $\overrightarrow{\mathrm{OB}}$，$\overrightarrow{\mathrm{OC}}$ で表せ．
  \item $\cos\angle\mathrm{BOC}$ と $\cos\angle\mathrm{BAC}$ の値を求めよ．
\end{enumerate}

$\vec a=(1,0,0)$，$\vec b=\Bigl(\cos\dfrac{2\pi}3,\sin\dfrac{2\pi}3,0\Bigr)$ とする．
\begin{enumerate}
  \item 長さ1の空間ベクトル $\vec c$ に対し $\cos\alpha=\vec a\cdot\vec c$，$\cos\beta=\vec b\cdot\vec c$（$0\leqq\alpha,\beta\leqq\pi$）とおく．次の不等式 $(*)$ が成り立つことを示せ．
  \[ (*)\quad\cos^2\alpha+\cos\alpha\cos\beta+\cos^2\beta\leqq\frac34 \]
  \item 不等式 $(*)$ をみたす $(\alpha,\beta)$（$0\leqq\alpha,\beta\leqq\pi$）の範囲を図示せよ．
\end{enumerate}

空間内の四面体 ABCD において，辺 AB，BC，CD，DA の中点をそれぞれ K，L，M，N，辺 AC の中点を P とする．
\begin{enumerate}
  \item $4\overrightarrow{\mathrm{MK}}\cdot\overrightarrow{\mathrm{LN}}=|\overrightarrow{\mathrm{AC}}|^2-|\overrightarrow{\mathrm{BD}}|^2$ を示せ．
  \item $\text{AB}=\text{CD}=\sqrt5$，$\text{BC}=\text{AD}=\sqrt{10}$，$\text{CA}=\text{BD}=\sqrt{13}$ のとき，四面体 ABCD は直方体の4頂点で作れることを示し，四面体 ABCD の体積を求めよ．
  \item (2) のとき，四面体 PKLN の体積を求めよ．
\end{enumerate}

座標空間において，$y$ 軸を含み $xz$ 平面との交線 $l$ が点 $(1,0,2\sqrt3)$ を通る平面を $H$ とする．$xy$ 平面上の曲線 $y=\sqrt3\sin^2x$ 上の点 P$(x,y,0)$ における接線の単位方向ベクトルで $x$ 成分が正のものを $\overrightarrow{\mathrm{PQ}}$ とする．P，Q を通り $z$ 軸に平行な直線が $H$ と交わる点をそれぞれ P$'$，Q$'$ とする．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{PQ}}$，$\overrightarrow{\mathrm{P'Q'}}$ の成分を $x$ で表せ．
  \item $\overrightarrow{\mathrm{PQ}}$ と $\overrightarrow{\mathrm{P'Q'}}$ のなす角を $\theta$ とするとき，$\sin\theta$ を $x$ で表し，$\theta$ のとりうる値の最小値を求めよ．
\end{enumerate}

平面上の四角形 ABCD を考える．
\begin{enumerate}
  \item ABCD が平行四辺形のとき，平面上の任意の点 P に対して $\text{PA}^2+\text{PC}^2-\text{PB}^2-\text{PD}^2$ は P によらない一定値であることを示し，その値を AC，BD で表せ．
  \item 逆に，$\text{PA}^2+\text{PC}^2-\text{PB}^2-\text{PD}^2$ が P によらず一定ならば，ABCD は平行四辺形であることを示せ．
\end{enumerate}

三角形 ABC において，$\vec p=\dfrac{\overrightarrow{\mathrm{AB}}}{\mathrm{AB}}$，$\vec q=\dfrac{\overrightarrow{\mathrm{BC}}}{\mathrm{BC}}$，$\vec r=\dfrac{\overrightarrow{\mathrm{CA}}}{\mathrm{CA}}$ とおく．
\begin{enumerate}
  \item $|\vec r-\vec q|^2$ を $\angle$C で表し，$|\vec r-\vec q|<|\vec q-\vec p|\iff\angle\mathrm B<\angle\mathrm C$ を示せ．
  \item $|\vec p+\vec q+\vec r|^2=3-2(\cos A+\cos B+\cos C)$ を示せ．
  \item $\cos A+\cos B+\cos C>1$ を用いて $|\vec p+\vec q+\vec r|<1$ を示し，$\vec p+\vec q+\vec r=\vec0$ となる三角形を答えよ．
\end{enumerate}

A，B，C を平面上の相異なる3点とし，AB の中点を M とする（M$\neq$C）．
\begin{enumerate}
  \item 点 P が $|\overrightarrow{\mathrm{PA}}+\overrightarrow{\mathrm{PB}}+2\overrightarrow{\mathrm{PC}}|^2=|\overrightarrow{\mathrm{PA}}+\overrightarrow{\mathrm{PB}}|^2+4|\overrightarrow{\mathrm{PC}}|^2$ をみたすとき，$(\overrightarrow{\mathrm{PA}}+\overrightarrow{\mathrm{PB}})\cdot\overrightarrow{\mathrm{PC}}$ を求めよ．
  \item この条件をみたす点 P の軌跡を求めよ．
  \item 点 B がこの軌跡上にあるとき，$\triangle$ABC はどのような三角形か．
\end{enumerate}

1辺の長さが1の正四面体 OABC で $\overrightarrow{\mathrm{OA}}=\vec a$，$\overrightarrow{\mathrm{OB}}=\vec b$，$\overrightarrow{\mathrm{OC}}=\vec c$ とする．線分 AB を $2:1$ に内分する点を L，線分 BC の中点を M，線分 OC を $t:(1-t)$ に内分する点を N（$0<t<1$）とする．線分 AM と線分 CL の交点を P，線分 OP と線分 LN の交点を Q とする．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{OP}}$ を $\vec a,\vec b,\vec c$ で表し，$|\overrightarrow{\mathrm{OP}}|$ の値を求めよ．
  \item $\overrightarrow{\mathrm{OQ}}$ を $t,\vec a,\vec b,\vec c$ で表せ．
  \item 三角形 QOC と三角形 QAM の面積が等しくなる $t$ の値を求めよ．
\end{enumerate}

空間に4点 A$(2,0,0)$，B$(0,4,0)$，C$(0,0,4)$，D$(3,1,1)$ がある．3点 A，B，C を含む平面を $T$ とする．
\begin{enumerate}
  \item 点 D から平面 $T$ に下ろした垂線の足 H の座標を求めよ．
  \item 平面 $T$ 上で，3点 A，B，C を通る円 $S$ の中心の座標と半径を求めよ．
  \item 点 P が円 $S$ の周上を動くとき，線分 DP の長さの最小値と，そのときの P の座標を求めよ．
\end{enumerate}

四面体 ABCD は各辺の長さが1の正四面体とする．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{AP}}=l\overrightarrow{\mathrm{AB}}+m\overrightarrow{\mathrm{AC}}+n\overrightarrow{\mathrm{AD}}$ で与えられる点 P が $|\overrightarrow{\mathrm{BP}}|=|\overrightarrow{\mathrm{CP}}|=|\overrightarrow{\mathrm{DP}}|$ をみたすならば $l=m=n$ であることを示し，$|\overrightarrow{\mathrm{BP}}|$ を $l$ で表せ．
  \item 四面体 PBCD と四面体 QACD がともに正四面体となるように，A，B，C，D と異なる点 P，Q をとる．PQ の長さと $\cos\angle$PCQ の値を求めよ．
\end{enumerate}

原点 O を通り $\vec d=(1,1,\sqrt2)$ に平行な直線 $l$ がある．O を頂点とする直円錐 $C$ の底面の中心 H は $l$ 上にあり，OH$=2$ である．点 A$(2,0,\sqrt2)$ は $C$ の底面の周上にある．
\begin{enumerate}
  \item H の座標を求め，$\cos\angle$AOH を求めよ．
  \item 点 P$(x,y,\sqrt2)$ が直円錐 $C$ の側面上にあるとき，$x,y$ のみたす関係式と範囲を求め，その曲線の概形を述べよ．
\end{enumerate}

正六角形 ABCDEF において，辺 CD の中点を G，辺 EF を $t:(1-t)$ に内分する点を H とする（$0<t<1$）．$\overrightarrow{\mathrm{AB}}=\vec a$，$\overrightarrow{\mathrm{AF}}=\vec b$ とする．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{AG}}$，$\overrightarrow{\mathrm{AH}}$ を $t,\vec a,\vec b$ で表せ．
  \item 直線 BE と直線 GH の交点を I とするとき，GI$:$IH を求めよ．
  \item 直線 AI と直線 DE の交点 K が辺 DE の中点となるとき，$t$ の値を求めよ．
\end{enumerate}

平行四辺形 ABCD の辺 AB を $1:2$ に内分する点を P，辺 AD の中点を Q とし，線分 PC と QB の交点を R とする．
\begin{enumerate}
  \item $\dfrac{\mathrm{PR}}{\mathrm{PC}}$ を求めよ．
  \item $\overrightarrow{\mathrm{RD}}=x\overrightarrow{\mathrm{RQ}}+y\overrightarrow{\mathrm{RC}}$ を満たす実数 $x,y$ を求めよ．
\end{enumerate}

平面上の点 A，B，C，P が $2\overrightarrow{\mathrm{PA}}+k\overrightarrow{\mathrm{PB}}+3\overrightarrow{\mathrm{PC}}=\vec0$（$k>0$）を満たしている．ただし A，B，C は同一直線上にない．
\begin{enumerate}
